Export.Routine:
#include Ensemble
 set ImportFromEdifecs = 0

 SET todayNum=$PIECE($HOROLOG,",",1)

 WRITE !, "IHC_TPManage on " _ $SYSTEM
 // set $NAMESPACE = "CORERULES"
 WRITE !, "NAMESPACE: " _ $NAMESPACE
 set sqlUsr = "cacheusr"
 set separator = "~! "
 set direc = "/home/cacheusr/TpManage/" // "/home/cacheusr/TpManage/" // "/home/lpjnaras/TpManage/"
 set flNm = direc _  "TpIds.txt" // TRANSACTIONTYPES.txt"  // TpIds.txt" // TradingPartners.txt"

 // set cmd = "java -cp /home/cacheusr/TpManage:/WORK/common/class/ojdbc8.jar edifecs/JdbcOracleConnection " _ direc 

 if (ImportFromEdifecs = 1)
 {
	 set cmd = "/home/cacheusr/TpManage/edifecs/cleanCmd"
	 set stat = ##class(IHC.ITF.ITFCOMMON.Utility).ExecuteShellCmd(cmd, "/itf-share/itf-tmp/lpjnaras/TpManage.out", "/itf-share/itf-tmp/lpjnaras/TpManage.err")

	 if (stat = 0)
	 {
		 WRITE !, "Created new TP files from Edifecs"
	 	// Clean the <ApplicationSettings>
	 	// set cleanCmd = "/home/cacheusr/TpManage/edifecs/cleanCmd"
	 	// Do ##class(IHC.ITF.ITFCOMMON.Utility).ExecuteShellCmd(cleanCmd, "/itf-share/itf-tmp/lpjnaras/TpManage.out", "/itf-share/itf-tmp/lpjnaras/TpManage.err")
	 }
	 else
	 {
		 WRITE !, "Error in " _ cmd
		 QUIT
	 }
 }



 /***
tpNms.txt

	 select p.name,b.name
	 from
	 "ECENABLEMENT_SH"."BIZROLEDEF" b, "ECENABLEMENT_SH"."PARTY"  p
	 where p.BIZROLEDEFSID = b.bizroledefsid;

tpIds.txt

	select  ind.identifiersid, ind.value, 
	DECODE(nvl(to_char(ind.comments), 'X12Identifier'), 'X12Identifier', 'BOTH', 'X12Identifier-GS','GS'), p.name
	from
	identifier ind, PARTY  p
	where ind.partysid = p.partysid
	and ind.value is not null
	order by p.name; 

IHC_TPManage.TRANSACTIONTYPES

 SELECT
distinct regexp_replace(trn.NAME, 'OutRT|OutB|InRT|InB', '')  as NAME
 , dir.caption as Direction, trn.CODE as TransactionSetId, trn.version, replace(regexp_replace(trn.description, 'Batch|Real Time',''), '- ','') as DESCRIPTION
FROM
    traderelationship rsh, TPMTRANSACTION trn, agreement ag,
    BIZDOCUMENTDEF bz,  entransactiondirection dir
    where rsh.tpmtransactionsid = trn.tpmtransactionsid
    and ag.tpmtransactionsid = trn.tpmtransactionsid
    and ag.Name like 'IMH%' and ag.Name not like '%Catch%' and ag.Name not like '%Test%' and ag.Name not like '%Custom%'
    and bz.BIZDOCUMENTDEFSID = trn.BIZDOCUMENTDEFSID
    and dir.enumid = TRANSACTIONDIRECTIONID
    order by  trn.CODE;

 ***/
 set dtTm = $ZDATETIME($HOROLOG,3, 1)
 if (##class(%File).Exists(flNm))
 {
     set line = 1
	 set fileObj = ##class(%File).%New(flNm)

	 set status = fileObj.Open("R")
	 set numRecs = 0, numDup = 0, numIns = 0, numErr = 0
	 while 'fileObj.AtEnd {
		 set text = fileObj.ReadLine(,.sc, .eol)
		 if $$$ISERR(sc) 
		 {
			 WRITE !, "End of File: " _sc _ ", " _ eol
			 QUIT
		 }
		 else
		 {

			 if ($L(text) <= 0)
			 {
			   continue
			 } 
			 set numRecs = numRecs + 1

			 if (flNm [ "TradingPartners" ) 
			{ //Trading Partner
				 set tpNm = $ZSTRIP($PIECE(text, separator, 2),"<>W")
			     // WRITE !, text _", length: " _ $L(text, separator)
			     /*
				 set modDt = $ZSTRIP($PIECE(text, separator, 29),"<>W")

				 if ((todayNum - $ZDATEH(modDt, 3)) > 30)
				 {
					 // WRITE !, tpNm _" modifed on " _ modDt
				 }
				 else
				 {
					 */
				     WRITE !, "Insert or update: " _ tpNm
					 set ediId = $ZSTRIP($PIECE(text, separator, 1),"<>W")

					 set typ = $ZSTRIP($PIECE(text, separator, 3),"<>W")
					 set tele = $ZSTRIP($PIECE(text, separator, 4),"<>W")
					 if (tele = "-")
					 {
						 set tele = "555-1212"
					 }
					 set em = $ZSTRIP($PIECE(text, separator, 5),"<>W")
					 if (em = "-")
					 {
						 set em = "TDB@"_tpNm
					 }

					 if ( (tpNm '= "") && (typ '= ""))
					 {
						 &SQL(INSERT INTO  IHC_TPManage.TradingPartner 
						 (ContactEmail, ContactName, ContactPhone, 
						 CreateID, CreatedDtTM, LastmodDtTM, LastmodID, Name, Type, EdifecsId)
						 values(:em, 'TBD', :tele,:sqlUsr,:dtTm,:dtTm,:sqlUsr,:tpNm,:typ,:ediId))
						 if (SQLCODE = 0)
						 {
							 // WRITE !, "Inserted " _ tpNm _ " / " _typ
							 set numIns = numIns + 1

							 set OutConn270RTAcks= $ZSTRIP($PIECE(text, separator, 7),"<>W")
							 set OutConn820Acks= $ZSTRIP($PIECE(text, separator, 8),"<>W")
							 set ElementSeparator= $ZSTRIP($PIECE(text, separator, 9),"<>W")
							 set ISACompElementSeparator= $ZSTRIP($PIECE(text, separator, 10),"<>W")
							 set OutConn271RT= $ZSTRIP($PIECE(text, separator, 11),"<>W")

							 set OutConn837DAcks= $ZSTRIP($PIECE(text, separator, 12),"<>W")
							 set OutConn278Acks= $ZSTRIP($PIECE(text, separator, 13),"<>W")
							 set OutConn276RTAcks= $ZSTRIP($PIECE(text, separator, 14),"<>W")
							 set OutConn277RT = $ZSTRIP($PIECE(text, separator, 15),"<>W")
							 set OutConn271B = $ZSTRIP($PIECE(text, separator, 16),"<>W")
							 set OutConn837PAcks= $ZSTRIP($PIECE(text, separator, 17),"<>W")
							 set AckUsag999RT= $ZSTRIP($PIECE(text, separator, 18),"<>W")
							 set OutConn270BAcks= $ZSTRIP($PIECE(text, separator, 19),"<>W")
							 set OutConn835= $ZSTRIP($PIECE(text, separator, 20),"<>W")
							 set OutConn277CA= $ZSTRIP($PIECE(text, separator, 21),"<>W")
							 set OutConn837IAcks= $ZSTRIP($PIECE(text, separator, 22),"<>W")
							 set AckUsage999= $ZSTRIP($PIECE(text, separator, 23),"<>W")
							 set OutConn277B= $ZSTRIP($PIECE(text, separator, 24),"<>W")
							 set AckUsageTA1= $ZSTRIP($PIECE(text, separator, 25),"<>W")
							 set AckUsageTA1RT= $ZSTRIP($PIECE(text, separator, 26),"<>W")
							 set OutConn276BAcks= $ZSTRIP($PIECE(text, separator, 27),"<>W")
							 set BatchingMode835= $ZSTRIP($PIECE(text, separator, 28),"<>W")

							  &SQL(INSERT INTO  IHC_TPManage.CustomFields 
							 (EdicTpId, AckUsage999, AckUsage999RT, AckUsageTA1, AckUsageTA1RT, BatchingMode835, 
							 ElementSeparator, ISACompElementSeparator, OutConn270BAcks, OutConn270RTAcks, OutConn271B, 
							 OutConn271RT, OutConn276BAcks, OutConn276RTAcks, OutConn277B, OutConn277CA, OutConn277RT, 
							 OutConn278Acks, OutConn820Acks, OutConn835, OutConn837DAcks, OutConn837IAcks, OutConn837PAcks)
							 values(:ediId, :AckUsage999, :AckUsage999RT, :AckUsageTA1, :AckUsageTA1RT, :BatchingMode835, 
							  :ElementSeparator, :ISACompElementSeparator, :OutConn270BAcks, :OutConn270RTAcks, :OutConn271B, 
							  :OutConn271RT, :OutConn276BAcks, :OutConn276RTAcks, :OutConn277B, :OutConn277CA, :OutConn277RT, 
							  :OutConn278Acks, :OutConn820Acks, :OutConn835, :OutConn837DAcks, :OutConn837IAcks, :OutConn837PAcks
							  		 ))
							 if (SQLCODE = 0)
							 {
								 WRITE !, "Inserted CustomFields " _ AckUsage999 _ " / " _ediId
							 }
							 else
							 {
								 WRITE !, SQLCODE _ ": " _ AckUsage999 _ " / " _ediId  _ " / " _ OutConn837PAcks
							 }
						 }


						 elseif (SQLCODE = "-119")
						 {
							 // WRITE !, "Duplicate: " _ tpNm _ " / " _typ
							 set numDup = numDup + 1

							 // Update
							 &SQL(UPDATE  IHC_TPManage.TradingPartner 
								set ContactEmail = :em, ContactPhone = :tele, 
									LastmodDtTM = :dtTm, LastmodID = :sqlUsr,  
									Type=:typ, EdifecsId = :ediId where Name = :tpNm)

							WRITE !, "  UPDATE " _ tpNm _ " - SQLCODE: " _ SQLCODE		
						 }
						 else
						 {
							 WRITE !, "SQLCODE: " _ SQLCODE _ ", TP: " _ tpNm _ ", Type: " _typ
							 set numErr= numErr + 1
						 }
					 }
					 else
					 {
						 WRITE !, "SKIP: " _ tpNm
					 }

				 // } No MOD date check


			 }
			 elseif (flNm [ "TpIds" ) {  // TpId
			 	set ediId = $ZSTRIP($PIECE(text, separator, 1),"<>W")
			 	set tpId = $ZSTRIP($PIECE(text, separator, 2),"<>W")			
				set tpNm = $ZSTRIP($PIECE(text, separator, 3),"<>W")
				set typ = $ZSTRIP($PIECE(text, separator, 4),"<>W")


				// write !, "TPID -> " _ line _ ". " _ tpNm _ ":" _ typ
				set line = line + 1

				if ((tpNm = "") || (tpId = ""))
				{
					continue
				}

				set tradingPartnerId = ""
				&SQL(select ID into :tradingPartnerId FROM IHC_TPManage.TradingPartner where Name = :tpNm)
				if SQLCODE '= 0
				{			
						WRITE !, "Error in finding TP for: " _  tpNm _ ", SQLCODE: " _ SQLCODE

				}
				if (tradingPartnerId = "")
				{
						WRITE !, "ID for TP is empty " _ tpNm

				}
				else
				{
					Set cm = ##class(IHC.TPManage.TPIDS).%New()
					#dim tp As IHC.TPManage.TradingPartner
					set tp = ##class(IHC.TPManage.TradingPartner).%OpenId(tradingPartnerId)
					if ($IsObject(tp))
					{
						set cm.TPFK = tp
						set cm.TPID = $ZSTRIP(tpId,"<>WC")
						set cm.Type =  $SELECT(typ="":"BOTH",typ="null":"BOTH",1:typ) 
						set cm.EdifecsID = ediId
						set cm.Name = tpNm _ " TpId"
						set cm.CreatedDtTM = dtTm
						set cm.LastmodDtTM = dtTm
						set cm.LastmodID = sqlUsr
						set cm.CreateID = sqlUsr

						set stat = cm.%Save()


						if ($$$ISOK(stat))
						{
							set numIns = numIns + 1
						}
						else
						{

							&SQL(SELECT count(*) into :numRows from IHC_TPManage.TPIDS where TPID = :tpId)
							// WRITE !, SQLCODE _", #: " _ numRows
							if ((SQLCODE = 0) && (numRows >= 1))
							{
								set numDup = numDup + 1
								if (numRows > 1)
								{
									WRITE !, " -***- Same TPID " _ tpId _ " exists multiple times ("_ numRows _ ") in IHC_TPManage.TPIDS: "  

									set myquery = "SELECT NAME, EdifecsID FROM IHC_TPManage.TPIDS where TPID = '" _ tpId _"'"
						    set tStatement = ##class(%SQL.Statement).%New()
							  set qStatus = tStatement.%Prepare(myquery)
							   if qStatus'=1 {write "%Prepare failed:" do $System.Status.DisplayError(qStatus) quit}
							  set rset = tStatement.%Execute()
							  while rset.%Next()
		  						{

										if SQLCODE = 0
										{			
												WRITE !, "  - Name: " _ rset.%Get("NAME") _ ", EdifecsID: " _ rset.%Get("EdifecsID")																	 
										}

		  						}

								}
								// WRITE !, "Duplicate TPID: " _ tpNm _ ", " _ tpId 
							}
							else
							{

								WRITE !, tpNm _ ", " _ tpId _ ", " _ tp _ ", " _ ediId _ ", " _ typ _ " - Save error: " _ stat
								set numErr= numErr + 1
							}
						}
					}
					else
					{
						WRITE !, tpNm _" not found in IHC.TPManage.TradingPartner"
					}

				} 
			} //TpId


			 else 
			{ //TRANSACTIONTYPES

				 set trNm = $ZSTRIP($PIECE(text, separator, 1),"<>W")
				 set direc = $ZSTRIP($PIECE(text, separator, 2),"<>W")
				 set type = $ZSTRIP($PIECE(text, separator, 3),"<>W")
				 set ver = $ZSTRIP($PIECE(text, separator, 4),"<>W")
				 set desc = $ZSTRIP($PIECE(text, separator, 5),"<>W")

				 if (trNm '= "")
				 {

					 &SQL(INSERT INTO  IHC_TPManage.TRANSACTIONTYPES
					  ( NAME,  TransactionSetId, VERSION,DESCRIPTION,
					 CreateID, CreatedDtTM, LastmodDtTM, LastmodID )
					 values(:trNm, :type,:ver,:desc
					 ,:sqlUsr,:dtTm,:dtTm,:sqlUsr))
					 if (SQLCODE = 0)
					 {
						 // WRITE !, "Inserted " _ trNm _ " / " _type
						 set numIns = numIns + 1
					 }
					 elseif (SQLCODE = "-119")
					 {
						 // WRITE !, "Duplicate: " _ trNm _ " / " _type
						 set numDup = numDup + 1
					 }
					 else
					 {
						 WRITE !, SQLCODE _ ": " _ trNm _ " / " _type
						 set numErr= numErr + 1
					 }
				 }


			 }

		 }



 	}
	do fileObj.Close()
    WRITE !, "DONE processing " _ flNm _", # of rows: " _ numRecs _ ", inserted: " _ numIns _ ", Duplicates: " _ numDup _", errors: " _ numErr
  }
  else
  {
	  WRITE !, "File can not be opened: " _ flNm
  }
  WRITE !, "----"
